#pragma once
namespace esphome::gym_native {
inline constexpr char ADMIN_PAGE[] = R"HTML(<!doctype html>
<html lang="nb"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenGym · Skjerminnstillinger</title>
<style>
:root{color-scheme:dark;--bg:#17191b;--surface:#202326;--line:#343a40;--text:#f6f7f8;--muted:#a8afb5;--lime:#b3f568}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,sans-serif}main{max-width:1080px;margin:auto;padding:32px 28px 64px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:48px}.brand{font-size:23px;font-weight:650}.status{color:var(--muted);font-size:14px}h1{font-size:clamp(28px,4vw,38px);line-height:1.2;margin:0 0 12px;font-weight:600;letter-spacing:-.7px}p{margin:0;color:var(--muted)}.intro{margin-bottom:32px}.grid{display:grid;grid-template-columns:1.15fr 1fr;gap:24px}.card{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:28px}h2{font-size:21px;font-weight:600;margin:0 0 28px}.row{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:24px 0}.row:first-of-type{margin-top:0}.muted{color:var(--muted);font-size:14px}.times{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:28px 0}.field label{display:block;font-size:14px;color:var(--muted);margin-bottom:10px}input[type=time],select{width:100%;border:1px solid #4b535a;border-radius:11px;background:var(--bg);color:var(--text);padding:12px 14px;font:inherit;min-height:48px}input[type=range]{width:100%;accent-color:var(--lime);margin:16px 0 24px;cursor:pointer}input[type=checkbox]{appearance:none;width:48px;height:28px;border-radius:20px;background:#555e64;position:relative;cursor:pointer;flex-shrink:0}input[type=checkbox]:after{content:"";position:absolute;top:4px;left:4px;width:20px;height:20px;background:#fff;border-radius:50%;transition:transform .12s}input[type=checkbox]:checked{background:var(--lime)}input[type=checkbox]:checked:after{transform:translateX(20px);background:#17220e}.value{font-variant-numeric:tabular-nums;color:var(--text)}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}button,.button{font:inherit;font-weight:550;display:inline-flex;justify-content:center;align-items:center;gap:10px;min-height:48px;padding:11px 20px;border-radius:11px;border:1px solid #4b535a;background:#2b3035;color:var(--text);cursor:pointer;text-decoration:none}button.primary{background:var(--lime);color:#17220e;border-color:var(--lime)}button:disabled{cursor:wait;opacity:.55}button:focus-visible,.button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--lime);outline-offset:3px}.wide{width:100%}dl{display:grid;grid-template-columns:1fr auto;gap:14px 24px;margin:0}dt{color:var(--muted)}dd{margin:0;text-align:right;font-variant-numeric:tabular-nums}.stack{display:grid;gap:24px}.download h2{margin-bottom:12px}.download .button{margin-top:24px}.message{min-height:28px;margin-top:20px;font-size:14px;white-space:pre-wrap;color:var(--lime)}.message.error{color:#ffbd99}footer{display:flex;justify-content:space-between;gap:24px;margin-top:32px;color:var(--muted);font-size:13px}@media(max-width:720px){main{padding:24px 20px 40px}.grid{grid-template-columns:1fr}.card{padding:24px}header{margin-bottom:36px}footer{flex-direction:column;gap:8px}}
</style>
<main><header><div class="brand">OpenGym</div><div class="status" id="connection">Henter skjermstatus …</div></header>
<section class="intro"><h1>Skjerminnstillinger</h1><p>Treningsskjermen hjemme</p></section>
<form id="settings"><div class="grid"><section class="card"><h2>Lys og nattmodus</h2>
<div class="row"><label for="enabled">Nattmodus</label><input type="checkbox" id="enabled" checked></div>
<div class="times"><div class="field"><label for="start">Slukk fra</label><input type="time" id="start" value="23:00" required></div><div class="field"><label for="end">På igjen</label><input type="time" id="end" value="07:00" required></div></div>
<div class="row"><label for="day">Lysstyrke på dagtid</label><output id="dayOut" class="value">100 %</output></div><input id="day" type="range" min="10" max="100" value="100">
<div class="row"><label for="night">Lys ved nattvekking</label><output id="nightOut" class="value">20 %</output></div><input id="night" type="range" min="5" max="50" value="20">
<div class="field"><label for="wake">Våken etter berøring om natten</label><select id="wake"><option value="1">1 minutt</option><option value="2">2 minutter</option><option value="5" selected>5 minutter</option><option value="10">10 minutter</option><option value="15">15 minutter</option><option value="30">30 minutter</option></select></div>
<div class="buttons"><button class="primary wide" id="save" type="submit" disabled>Lagre innstillinger</button></div><p class="message" id="result" role="status" aria-live="polite"></p>
</section><div class="stack"><section class="card"><h2>Skjermen nå</h2><dl><dt>Skjermlys</dt><dd id="display">—</dd><dt>Firmware</dt><dd id="version">—</dd><dt>Oppetid</dt><dd id="uptime">—</dd><dt>Lokal tid</dt><dd id="clock">—</dd><dt>Wi-Fi</dt><dd id="wifi">—</dd></dl><div class="buttons"><button type="button" id="on" disabled>Vekk skjermen</button><button type="button" id="off" disabled>Slukk skjermen</button></div></section>
<section class="card download"><h2>Diagnostikk</h2><p>Versjon, tilkobling og skjerminnstillinger. Ingen passord eller treningshistorikk.</p><a class="button" href="/admin/diagnostics.json" download>Last ned diagnostikk</a></section></div></div></form>
<footer><span id="address"></span><span>Tidssone: Europe/Oslo</span></footer></main>
<script>
'use strict';
const $=id=>document.getElementById(id);let current=null,dirty=false,busy=false;
const fields=['enabled','start','end','day','night','wake'];
const timeText=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
const minute=s=>{if(!/^\d{2}:\d{2}$/.test(s))throw Error('Velg et gyldig klokkeslett.');const [h,m]=s.split(':').map(Number);if(h>23||m>59)throw Error('Ugyldig klokkeslett.');return h*60+m;};
function message(text,error=false){$('result').textContent=text;$('result').classList.toggle('error',error);}
function outputs(){$('dayOut').textContent=$('day').value+' %';$('nightOut').textContent=$('night').value+' %';}
function controls(){for(const id of ['save','on','off',...fields])$(id).disabled=busy||!current;}
async function request(path,method='GET'){const r=await fetch(path,{method,cache:'no-store',credentials:'same-origin',headers:{'X-Requested-With':'OpenGymAdmin'}});if(!r.ok)throw Error(r.status===401?'Innlogging kreves.':'Skjermen svarte ikke som forventet ('+r.status+').');return method==='GET'?r.json():null;}
function render(s){current=s;$('connection').textContent=s.wifiConnected?'Tilkoblet':'Wi-Fi frakoblet';$('version').textContent=s.version;$('display').textContent=s.displayOn?'På · '+s.brightness+' %':'Av';$('uptime').textContent=Math.floor(s.uptimeSeconds/3600)+' t '+Math.floor(s.uptimeSeconds/60)%60+' min';$('clock').textContent=s.clockValid?s.localTime:'Ikke synkronisert';$('wifi').textContent=s.wifiConnected?'Tilkoblet':'Frakoblet';if(!dirty){$('enabled').checked=s.nightEnabled;$('start').value=timeText(s.nightStart);$('end').value=timeText(s.nightEnd);$('day').value=s.dayBrightness;$('night').value=s.nightBrightness;if(!$('wake').querySelector('option[value="'+s.wakeMinutes+'"]')){const o=document.createElement('option');o.value=s.wakeMinutes;o.textContent=s.wakeMinutes+' minutter';$('wake').appendChild(o);}$('wake').value=s.wakeMinutes;outputs();}controls();}
async function load(){const s=await request('/admin/status');render(s);return s;}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function until(test){for(let i=0;i<20;i++){const s=await load();if(test(s))return s;await delay(300);}throw Error('Endringen er ikke bekreftet. Hent status og prøv igjen.');}
for(const id of fields)$(id).addEventListener('input',()=>{dirty=true;outputs();message('Ulagrede endringer');});
$('settings').addEventListener('submit',async event=>{event.preventDefault();if(!current||busy)return;busy=true;controls();message('Lagrer …');try{const wanted={nightEnabled:$('enabled').checked,nightStart:minute($('start').value),nightEnd:minute($('end').value),dayBrightness:Number($('day').value),nightBrightness:Number($('night').value),wakeMinutes:Number($('wake').value)};if(wanted.nightEnabled&&wanted.nightStart===wanted.nightEnd)throw Error('Velg forskjellig start og slutt for nattmodus.');for(const key of ['nightStart','nightEnd','dayBrightness','nightBrightness','wakeMinutes'])if(wanted[key]!==current[key])await request('/number/'+encodeURIComponent(current.routes[key])+'/set?value='+wanted[key],'POST');if(wanted.nightEnabled!==current.nightEnabled)await request('/switch/'+encodeURIComponent(current.routes.nightEnabled)+(wanted.nightEnabled?'/turn_on':'/turn_off'),'POST');let s=await until(x=>Object.keys(wanted).every(k=>x[k]===wanted[k]));const sequence=s.storeSequence;await request('/button/'+encodeURIComponent(s.routes.save)+'/press','POST');s=await until(x=>x.storeSequence>sequence);if(!s.settingsStored)throw Error('Endringene kunne ikke lagres i fast minne.');dirty=false;render(s);message('Innstillingene er lagret.');}catch(e){message(e.message,true);}finally{busy=false;controls();}});
for(const [id,on] of [['on',true],['off',false]])$(id).addEventListener('click',async()=>{if(!current||busy)return;busy=true;controls();message(on?'Vekker skjermen …':'Slukker skjermen …');try{await request('/light/'+encodeURIComponent(current.routes.light)+(on?'/turn_on':'/turn_off'),'POST');await until(s=>s.displayOn===on);message(on?'Skjermen er på.':'Skjermen er av.');}catch(e){message(e.message,true);}finally{busy=false;controls();}});
$('address').textContent=window.location.host;
load().catch(e=>message(e.message,true));setInterval(()=>{if(!busy)load().catch(e=>{$('connection').textContent='Ingen forbindelse';message(e.message,true);});},8000);
</script></html>
)HTML";
}
